CREATE EXTERNAL ACCESS INTEGRATION my_eai
    ALLOWED_NETWORK_RULES = (my_egress_rule)
    ENABLED = TRUE;

CREATE OR REPLACE EXTERNAL ACCESS INTEGRATION my_eai
    ALLOWED_NETWORK_RULES = (rule_1, my_db.my_schema.rule_2)
    ALLOWED_API_AUTHENTICATION_INTEGRATIONS = (my_oauth_integration)
    ALLOWED_AUTHENTICATION_SECRETS = (my_db.my_schema.my_secret, other_secret)
    ENABLED = FALSE
    COMMENT = 'egress to the payments API';

CREATE EXTERNAL ACCESS INTEGRATION my_eai
    ALLOWED_NETWORK_RULES = (my_egress_rule)
    ALLOWED_API_AUTHENTICATION_INTEGRATIONS = NONE
    ALLOWED_AUTHENTICATION_SECRETS = ALL
    ENABLED = TRUE;
